package com.tripmateai.entity;
import com.tripmateai.enums.ExpenseStatus; import jakarta.persistence.*; import jakarta.validation.constraints.*; import lombok.*; import java.math.BigDecimal; import java.util.*;
@Entity @Table(name="group_expenses",indexes=@Index(name="idx_group_expenses_group",columnList="group_id")) @Getter @Setter @NoArgsConstructor @EqualsAndHashCode(callSuper=true,onlyExplicitlyIncluded=true) @ToString
public class GroupExpense extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="group_id",nullable=false) @ToString.Exclude private Group group; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="paid_by_member_id",nullable=false) @ToString.Exclude private GroupMember paidBy; @NotBlank @Size(max=200) @Column(nullable=false,length=200) private String description; @NotNull @DecimalMin("0.01") @Column(nullable=false,precision=12,scale=2) private BigDecimal amount; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private ExpenseStatus status=ExpenseStatus.SPLIT; @OneToMany(mappedBy="groupExpense",fetch=FetchType.LAZY,cascade=CascadeType.ALL,orphanRemoval=true) @ToString.Exclude private List<GroupExpenseShare> shares=new ArrayList<>(); }
